// friday13.cs — Friday the 13th experiments (proleptic Gregorian)

// 1. Find the earliest Friday the 13th starting at 0001-01-01
var date = new DateTime(1, 1, 13); // start on the 13th of Jan 0001
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// 2. Count Friday the 13ths in a full 400-year cycle (0001-01-01 to 0400-12-31)
//    The Gregorian calendar repeats every 400 years exactly.
int count = 0;
var d = new DateTime(1, 1, 13);
var end = new DateTime(400, 12, 13);

while (d <= end)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
    d = d.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// 3. Bonus: distribution by month
var byMonth = new int[12];
d = new DateTime(1, 1, 13);
while (d <= end)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        byMonth[d.Month - 1]++;
    d = d.AddMonths(1);
}

Console.WriteLine("\nDistribution by month:");
for (int m = 0; m < 12; m++)
    Console.WriteLine($"  {new DateTime(2000, m + 1, 1):MMMM,-12} {byMonth[m]}");

